'use strict';

class InventoryError extends Error {
  constructor(message, code) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends InventoryError {
  constructor(message) {
    super(message, 'VALIDATION');
  }
}

class UnknownSkuError extends InventoryError {
  constructor(sku) {
    super(`unknown sku: ${sku}`, 'UNKNOWN_SKU');
    this.sku = sku;
  }
}

class UnknownOrderError extends InventoryError {
  constructor(orderId) {
    super(`unknown order: ${orderId}`, 'UNKNOWN_ORDER');
    this.orderId = orderId;
  }
}

class InsufficientStockError extends InventoryError {
  constructor(sku, requested, available) {
    super(`insufficient stock for ${sku}: requested ${requested}, available ${available}`, 'INSUFFICIENT_STOCK');
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

class OrderStateError extends InventoryError {
  constructor(orderId, status, action) {
    super(`cannot ${action} order ${orderId}: it is ${status}`, 'ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  InventoryError,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
};
'use strict';

module.exports = {
  ...require('./inventory'),
  ...require('./errors'),
  ...require('./store')
};
'use strict';

const { Store } = require('./store');
const { KeyedMutex } = require('./keyed-mutex');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;
const ORDER_PREFIX = 'order:';
const SKU_PREFIX = 'sku:';

// The store has no compare-and-set, so every read-modify-write runs under a
// lock on the keys it touches. Locks are kept per store, not per service, so
// two services built on the same store still exclude each other.
const locksByStore = new WeakMap();

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. A call that
 * changes records holds the lock of each record's key for the whole
 * read-modify-write. It takes at most one order lock, before any SKU lock,
 * and takes its SKU locks in sorted order, so calls cannot deadlock. Calls
 * that share no SKU and no order never wait for each other.
 */
class InventoryService {
  #locks;

  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    assertStore(store);
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
    this.#locks = locksFor(store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    const key = skuKey(sku);
    return this.#locks.withLock(key, async () => {
      const item = (await this.store.get(key)) || { stock: 0, reserved: 0, sold: 0 };
      const updated = { ...item, stock: item.stock + qty };
      await this.store.set(key, updated);
      return { sku, ...updated };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    // Copied before the first await so later changes to the caller's array
    // cannot alter what gets held.
    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
    const key = orderKey(orderId);
    return this.#locks.withLock(key, async () => {
      // A concurrent retry waits for the order lock, then finds this record.
      const existing = await this.store.get(key);
      if (existing) {
        return toReservation(existing);
      }
      return this.#writeOrder(lines, holdUnits, () => ({
        orderId,
        items: lines,
        status: 'reserved',
        createdAt: this.now()
      }));
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#locks.withLock(orderKey(orderId), async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return this.#writeOrder(order.items, sellUnits, () => ({ ...order, status: 'committed' }));
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#locks.withLock(orderKey(orderId), async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return this.#writeOrder(order.items, returnUnits, () => ({ ...order, status: 'released' }));
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const released = [];
    // One order at a time keeps the sweep's load on the store low while
    // checkout is running; it holds no lock between orders.
    for (const key of await this.store.keys(ORDER_PREFIX)) {
      // Committed and released are final states, so this unlocked read is
      // enough to skip an order. A stale reservation is re-read under its
      // lock because a worker may commit or release it in the meantime.
      if (!isStale(await this.store.get(key), cutoff)) {
        continue;
      }
      const reservation = await this.#locks.withLock(key, async () => {
        const order = await this.store.get(key);
        if (!isStale(order, cutoff)) {
          return null;
        }
        return this.#writeOrder(order.items, returnUnits, () => ({ ...order, status: 'released' }));
      });
      if (reservation) {
        released.push(reservation.orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  /**
   * Under the locks of every SKU in `lines`, compute each SKU's new counters
   * with `adjust(item, qty, sku)`, then write them and the order record from
   * `makeOrder()`. Every line is checked before anything is written, so an
   * `adjust` that throws leaves the store untouched. The caller must hold the
   * order's lock.
   */
  async #writeOrder(lines, adjust, makeOrder) {
    const keys = lines.map(({ sku }) => skuKey(sku));
    return this.#locks.withLocks(keys, async () => {
      const items = await Promise.all(keys.map(key => this.store.get(key)));
      const writes = lines.map(({ sku, qty }, i) => {
        if (!items[i]) {
          throw new UnknownSkuError(sku);
        }
        return { key: keys[i], previous: items[i], value: adjust(items[i], qty, sku) };
      });
      const order = makeOrder();
      await writeAllOrNothing(this.store, writes, { key: orderKey(order.orderId), value: order });
      return toReservation(order);
    });
  }
}

function holdUnits(item, qty, sku) {
  const free = item.stock - item.reserved;
  if (free < qty) {
    throw new InsufficientStockError(sku, qty, free);
  }
  return { ...item, reserved: item.reserved + qty };
}

function sellUnits(item, qty) {
  return { ...item, stock: item.stock - qty, reserved: item.reserved - qty, sold: item.sold + qty };
}

function returnUnits(item, qty) {
  return { ...item, reserved: item.reserved - qty };
}

function isStale(order, cutoff) {
  return order.status === 'reserved' && order.createdAt < cutoff;
}

/**
 * Write the SKU counters, then the order record, so an order's status only
 * changes after all of its counters have. If a write fails, the counters
 * already written are put back before the error is rethrown. The caller holds
 * the lock of every key involved. A rejected `set` is assumed not to have
 * been applied.
 */
async function writeAllOrNothing(store, skuWrites, orderWrite) {
  const written = [];
  try {
    // Sequential, so the first failure stops later writes and `written` is
    // exactly what has to be restored.
    for (const write of skuWrites) {
      await store.set(write.key, write.value);
      written.push(write);
    }
    await store.set(orderWrite.key, orderWrite.value);
  } catch (error) {
    await restore(store, written.reverse(), error);
    throw error;
  }
}

async function restore(store, writes, cause) {
  const failed = [];
  for (const write of writes) {
    try {
      await store.set(write.key, write.previous);
    } catch (error) {
      failed.push({ key: write.key, error });
    }
  }
  if (failed.length > 0) {
    const keys = failed.map(({ key }) => key).join(', ');
    throw new AggregateError(
      [cause, ...failed.map(({ error }) => error)],
      `store write failed, then restoring ${keys} failed too; those counters need manual repair`
    );
  }
}

function locksFor(store) {
  let locks = locksByStore.get(store);
  if (!locks) {
    locks = new KeyedMutex();
    locksByStore.set(store, locks);
  }
  return locks;
}

function skuKey(sku) {
  return `${SKU_PREFIX}${sku}`;
}

function orderKey(orderId) {
  return `${ORDER_PREFIX}${orderId}`;
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertStore(store) {
  if (!store || ['get', 'set', 'keys'].some(method => typeof store[method] !== 'function')) {
    throw new ValidationError('store must provide get, set and keys methods');
  }
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

module.exports = { InventoryService, DEFAULT_TTL_MS };
'use strict';

/**
 * In-process mutual exclusion keyed by string.
 *
 * Waiters on a key are served in arrival order. A key's entry is removed as
 * soon as nobody holds or waits for it, so memory tracks in-flight calls
 * rather than every key ever locked.
 */
class KeyedMutex {
  // key -> callbacks waiting for it. A key is held exactly while it has an entry.
  #queues = new Map();

  /**
   * Wait for `key` and take it. Resolves to a function that gives the key to
   * the next waiter; calling that function more than once has no effect.
   */
  acquire(key) {
    const queue = this.#queues.get(key);
    if (queue === undefined) {
      this.#queues.set(key, []);
      return Promise.resolve(this.#releaser(key));
    }
    return new Promise(resolve => queue.push(() => resolve(this.#releaser(key))));
  }

  /**
   * Run `fn` while holding every key in `keys`, and release them when it
   * settles. Keys are taken in sorted order, so calls whose key sets overlap
   * cannot deadlock on each other.
   */
  async withLocks(keys, fn) {
    const ordered = [...new Set(keys)].sort();
    const releases = [];
    try {
      // One at a time: waiting on several keys at once would give up the
      // sorted order that prevents deadlock.
      for (const key of ordered) {
        releases.push(await this.acquire(key));
      }
      return await fn();
    } finally {
      for (const release of releases.reverse()) {
        release();
      }
    }
  }

  /** Run `fn` while holding `key`. */
  withLock(key, fn) {
    return this.withLocks([key], fn);
  }

  /** Number of keys currently held. */
  get size() {
    return this.#queues.size;
  }

  #releaser(key) {
    let released = false;
    return () => {
      if (released) {
        return;
      }
      released = true;
      const queue = this.#queues.get(key);
      const next = queue.shift();
      if (next) {
        next();
      } else {
        this.#queues.delete(key);
      }
    };
  }
}

module.exports = { KeyedMutex };
'use strict';

// In-memory key-value store with the latency profile of the Redis cluster
// used in production: every call yields to the event loop before it reads or
// writes, so concurrent callers interleave the way they do against the real
// store. Values are copied on the way in and out.
class Store {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await tick();
    const value = this.data.get(key);
    return value === undefined ? undefined : structuredClone(value);
  }

  async set(key, value) {
    await tick();
    this.data.set(key, structuredClone(value));
  }

  async keys(prefix) {
    await tick();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

module.exports = { Store };
'use strict';

const assert = require('node:assert/strict');
const { InventoryService, Store, UnknownOrderError } = require('../src');

/** A service stocked with `stock` ({ sku: qty }). */
async function stockedService(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

/** Let `n` rounds of store latency pass. */
async function ticks(n) {
  for (let i = 0; i < n; i++) {
    await new Promise(resolve => setImmediate(resolve));
  }
}

/** Reject with `message` if `promise` has not settled within `ms`. */
async function within(ms, promise, message) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(message)), ms);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

/** Resolves to true if `promise` settles within `ms`, false otherwise. */
async function settlesWithin(ms, promise) {
  let timer;
  const timeout = new Promise(resolve => {
    timer = setTimeout(() => resolve(false), ms);
  });
  try {
    return await Promise.race([promise.then(() => true, () => true), timeout]);
  } finally {
    clearTimeout(timer);
  }
}

/** Store whose calls for chosen keys can be held until the test lets them through. */
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  /**
   * Hold every get/set of `key` until `open()` is called. `arrived` resolves
   * when the first call for the key reaches the gate.
   */
  gate(key) {
    let open;
    let arrive;
    const opened = new Promise(resolve => { open = resolve; });
    const arrived = new Promise(resolve => { arrive = resolve; });
    this.gates.set(key, { opened, arrive });
    return {
      arrived,
      open: () => {
        this.gates.delete(key);
        open();
      }
    };
  }

  async get(key) {
    await this.pass(key);
    return super.get(key);
  }

  async set(key, value) {
    await this.pass(key);
    return super.set(key, value);
  }

  async pass(key) {
    const gate = this.gates.get(key);
    if (gate) {
      gate.arrive();
      await gate.opened;
    }
  }
}

/** Store that rejects chosen calls, to model a store outage mid-operation. */
class FlakyStore extends Store {
  constructor() {
    super();
    this.plans = new Map();
  }

  /** Reject the `calls`-th (1-based, counted from now) `method` calls on `key`. */
  fail(method, key, calls) {
    this.plans.set(`${method} ${key}`, { calls: new Set(calls), seen: 0 });
  }

  async get(key) {
    this.maybeFail('get', key);
    return super.get(key);
  }

  async set(key, value) {
    this.maybeFail('set', key);
    return super.set(key, value);
  }

  maybeFail(method, key) {
    const plan = this.plans.get(`${method} ${key}`);
    if (!plan) {
      return;
    }
    plan.seen += 1;
    if (plan.calls.has(plan.seen)) {
      throw new Error(`store unavailable: ${method} ${key}`);
    }
  }
}

/** Store that hands out and keeps live references instead of copies. */
class SharedReferenceStore {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    return this.data.get(key);
  }

  async set(key, value) {
    this.data.set(key, value);
  }

  async keys(prefix) {
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

/** Deterministic PRNG (mulberry32) so a failing random run can be replayed. */
function seededRandom(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Check every SKU's counters against the orders that exist.
 *
 * `added` is the total stock added per SKU; `orderIds` lists every orderId
 * the test tried to reserve. `reserved` must equal the units of reserved
 * orders, `sold` the units of committed orders, `stock` the units added minus
 * those sold, and available stock must not be negative.
 */
async function assertLedger(svc, added, orderIds) {
  const expected = Object.fromEntries(Object.keys(added).map(sku => [sku, { reserved: 0, sold: 0 }]));
  const statuses = { reserved: 0, committed: 0, released: 0, missing: 0 };
  for (const orderId of new Set(orderIds)) {
    let order;
    try {
      order = await svc.getOrder(orderId);
    } catch (error) {
      assert.ok(error instanceof UnknownOrderError, `unexpected error reading ${orderId}: ${error}`);
      statuses.missing += 1;
      continue;
    }
    statuses[order.status] += 1;
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') expected[sku].sold += qty;
    }
  }
  for (const [sku, total] of Object.entries(added)) {
    const snap = await svc.snapshot(sku);
    assert.deepEqual(
      snap,
      { sku, stock: total - expected[sku].sold, reserved: expected[sku].reserved, sold: expected[sku].sold },
      `counters for ${sku} do not match the order ledger`
    );
    assert.ok(snap.stock - snap.reserved >= 0, `${sku} has negative available stock`);
  }
  return statuses;
}

module.exports = {
  stockedService,
  ticks,
  within,
  settlesWithin,
  GatedStore,
  FlakyStore,
  SharedReferenceStore,
  seededRandom,
  assertLedger
};
# inventory-service

Stock reservations for checkout. `InventoryService` keeps three counters per
SKU (`stock`, `reserved`, `sold`) and moves orders from `reserved` to either
`committed` or `released`. The store is a key-value store with `get`, `set`
and `keys`.

```js
const { InventoryService, InsufficientStockError } = require('./src');

const inventory = new InventoryService(); // or { store, reservationTtlMs, now }
await inventory.addStock('sneaker-limited', 250);

try {
  await inventory.reserve('order-17', [{ sku: 'sneaker-limited', qty: 1 }]);
  await inventory.commit('order-17'); // or inventory.release('order-17')
} catch (err) {
  if (!(err instanceof InsufficientStockError)) throw err;
}

await inventory.expire(); // releases reservations older than the TTL
```

## INC-5521: causes and fixes

Every symptom in `ISSUE.md` came from one of two problems. Each method did
read-modify-write on store records with no mutual exclusion, and the store
yields between every read and write, so concurrent calls overwrote each
other's work. Separately, two code paths ignored an order's state.

| Symptom | Cause | Fix |
| --- | --- | --- |
| 263 orders confirmed on 250 units | Concurrent `reserve` calls read the same `reserved` value, and each wrote back its own increment, so all but one hold were lost. | Every write to a SKU record happens under that SKU's lock. |
| `reserved` negative after the sale | `expire()` released every order past the TTL, committed ones included, and `release()` accepted committed orders, so units that had already been sold were subtracted from `reserved` a second time. Concurrent release/commit/expire of one order could also each apply their change. | `release` rejects committed orders with `OrderStateError`, as its doc comment says. `expire` only touches orders that are still `reserved`, and re-checks under the order lock. |
| A retried checkout held units twice | `reserve` checked for an existing order, then held stock, then wrote the order. A retry that arrived before the order record existed held the stock again. | `reserve` holds the order's lock from the existence check until the record is written, so a retry waits and then returns the first reservation. |
| A rejected bundle left its other item held | `reserve` held items one by one and threw on the first short item without undoing earlier holds. No order record was written, so `expire` could never find the hold. | All items are checked under their locks before anything is written. |
| `sold` higher than shipped orders | Two concurrent `commit`s of one order both saw `reserved` and both added to `sold`. `expire` could also flip a committed order to `released` after its units were counted as sold. | `commit` runs under the order lock. `expire` skips committed orders. |

`addStock` had the same lost-update race and takes the SKU lock too.

The tests in `tests/incident-5521.test.js` reproduce each row. 17 of the 18
fail against the previous implementation. The one that passes is a
regression guard: a reservation rejected for stock must not block a retry.

## Concurrency design

`src/keyed-mutex.js` is a FIFO lock per string key. The service locks the
same keys it stores (`sku:<sku>`, `order:<orderId>`):

- `addStock` locks its SKU.
- `reserve`, `commit` and `release` lock the order, then all of the order's
  SKUs.
- `expire` reads orders without a lock to skip committed and released ones
  (both states are final). For each stale reservation it takes that order's
  lock and SKU locks, and checks the order again before releasing it.
- `available`, `snapshot`, `getItem` and `getOrder` read a single record and
  take no lock.

**No deadlocks.** A call holds at most one order lock, takes it before any
SKU lock, and takes its SKU locks in sorted order. Every call therefore
acquires locks in the same global order.

**No global lock.** Calls that share no SKU and no order never wait for each
other. INC-5490 put everything behind one lock and cut throughput by 90%;
`tests/isolation-and-recovery.test.js` stalls a call inside the store and
checks that calls on other SKUs and orders still finish.

**Lock scope.** Locks live in a `WeakMap` keyed by the store object, so two
`InventoryService` instances built on the same store also exclude each
other. Keys are dropped from the lock table once nobody holds or waits for
them, so memory tracks in-flight calls rather than the SKU catalogue.

**Hot SKUs still serialize.** Every reservation of `sneaker-limited` takes
the same lock, which is the only way to stop overselling with a store that
has no compare-and-set. The lock is held for about three store round trips
per call.

### Store failures

Counter writes happen before the order record write, so an order's status
only changes after all of its counters have. If a write rejects, the
counters already written are restored from the values read under the lock,
and the original error is rethrown. If a restore also fails, the call
rejects with an `AggregateError` listing both errors and naming the keys that
need repair. This assumes a rejected `set` did not apply.

The service sets no timeouts on store calls. A timeout that gave up the lock
while a write was still in flight would let that write land later over
someone else's update. Store call timeouts belong in the store client, where
a timed-out command actually fails.

## Behaviour changes

The public API is unchanged: same methods, arguments, return values and
error types. Three behaviours now match the doc comments where they did not
before:

- `release` of a committed order rejects with `OrderStateError`.
- `expire` releases only orders still in `reserved`, and returns only the ids
  it released on that call.
- The constructor throws `ValidationError` for a store that lacks `get`,
  `set` or `keys`.

## Assumptions and limits

- **One process.** The locks are in-process. The incident's 40 workers are
  modelled as concurrent callers of one service, as the task states. Workers
  in separate processes against a shared Redis would need atomic operations
  in the store (`WATCH`/`MULTI` or a Lua script), which `get`/`set`/`keys`
  cannot express.
- **Existing bad data is not repaired.** The fix stops new damage; SKUs whose
  counters went wrong in production stay wrong until someone corrects them.
  A SKU's correct `reserved` is the sum of `qty` over orders in `reserved`
  status that include it, which also clears holds leaked by retries and
  rejected bundles. `sold` cannot be fully rebuilt from order records,
  because the old `expire` flipped committed orders to `released`; use
  shipment records for it. A repair script is a separate process and does
  not share the in-process locks, so run it with checkout paused.
  `assertLedger` in `tests/helpers.js` computes the invariant and is a
  starting point.
- `expire` walks orders one at a time and holds locks only while releasing
  one order, so a long sweep delays only calls that touch that order or its
  SKUs.

## Tests

```sh
npm test
```

| File | Covers |
| --- | --- |
| `tests/inventory.test.js` | Public API behaviour, validation, TTL boundary, unicode |
| `tests/incident-5521.test.js` | One `describe` per incident symptom, plus a 40-worker flash-sale replay |
| `tests/isolation-and-recovery.test.js` | No waiting across unrelated SKUs/orders, store failure rollback, non-cloning stores, seeded random stress |
| `tests/keyed-mutex.test.js` | Lock ordering, FIFO, cleanup, deadlock freedom |

The race tests rely on the store yielding to the event loop on every call,
as `src/store.js` does. The "offset sweep" tests start a second call 0–8
store round trips after the first. Calls started at the same instant also
lose each other's writes, which can hide a double hold or double commit, so
the sweep makes the second call land at every stage of the first.
