'use strict';

const { Store } = require('./store');
const { KeyedMutex } = require('./keyed-mutex');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;
const ORDER_PREFIX = 'order:';
const SKU_PREFIX = 'sku:';

// The store has no compare-and-set, so every read-modify-write runs under a
// lock on the keys it touches. Locks are kept per store, not per service, so
// two services built on the same store still exclude each other.
const locksByStore = new WeakMap();

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. A call that
 * changes records holds the lock of each record's key for the whole
 * read-modify-write. It takes at most one order lock, before any SKU lock,
 * and takes its SKU locks in sorted order, so calls cannot deadlock. Calls
 * that share no SKU and no order never wait for each other.
 */
class InventoryService {
  #locks;

  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    assertStore(store);
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
    this.#locks = locksFor(store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    const key = skuKey(sku);
    return this.#locks.withLock(key, async () => {
      const item = (await this.store.get(key)) || { stock: 0, reserved: 0, sold: 0 };
      const updated = { ...item, stock: item.stock + qty };
      await this.store.set(key, updated);
      return { sku, ...updated };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    // Copied before the first await so later changes to the caller's array
    // cannot alter what gets held.
    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
    const key = orderKey(orderId);
    return this.#locks.withLock(key, async () => {
      // A concurrent retry waits for the order lock, then finds this record.
      const existing = await this.store.get(key);
      if (existing) {
        return toReservation(existing);
      }
      return this.#writeOrder(lines, holdUnits, () => ({
        orderId,
        items: lines,
        status: 'reserved',
        createdAt: this.now()
      }));
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#locks.withLock(orderKey(orderId), async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return this.#writeOrder(order.items, sellUnits, () => ({ ...order, status: 'committed' }));
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#locks.withLock(orderKey(orderId), async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return this.#writeOrder(order.items, returnUnits, () => ({ ...order, status: 'released' }));
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const released = [];
    // One order at a time keeps the sweep's load on the store low while
    // checkout is running; it holds no lock between orders.
    for (const key of await this.store.keys(ORDER_PREFIX)) {
      // Committed and released are final states, so this unlocked read is
      // enough to skip an order. A stale reservation is re-read under its
      // lock because a worker may commit or release it in the meantime.
      if (!isStale(await this.store.get(key), cutoff)) {
        continue;
      }
      const reservation = await this.#locks.withLock(key, async () => {
        const order = await this.store.get(key);
        if (!isStale(order, cutoff)) {
          return null;
        }
        return this.#writeOrder(order.items, returnUnits, () => ({ ...order, status: 'released' }));
      });
      if (reservation) {
        released.push(reservation.orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  /**
   * Under the locks of every SKU in `lines`, compute each SKU's new counters
   * with `adjust(item, qty, sku)`, then write them and the order record from
   * `makeOrder()`. Every line is checked before anything is written, so an
   * `adjust` that throws leaves the store untouched. The caller must hold the
   * order's lock.
   */
  async #writeOrder(lines, adjust, makeOrder) {
    const keys = lines.map(({ sku }) => skuKey(sku));
    return this.#locks.withLocks(keys, async () => {
      const items = await Promise.all(keys.map(key => this.store.get(key)));
      const writes = lines.map(({ sku, qty }, i) => {
        if (!items[i]) {
          throw new UnknownSkuError(sku);
        }
        return { key: keys[i], previous: items[i], value: adjust(items[i], qty, sku) };
      });
      const order = makeOrder();
      await writeAllOrNothing(this.store, writes, { key: orderKey(order.orderId), value: order });
      return toReservation(order);
    });
  }
}

function holdUnits(item, qty, sku) {
  const free = item.stock - item.reserved;
  if (free < qty) {
    throw new InsufficientStockError(sku, qty, free);
  }
  return { ...item, reserved: item.reserved + qty };
}

function sellUnits(item, qty) {
  return { ...item, stock: item.stock - qty, reserved: item.reserved - qty, sold: item.sold + qty };
}

function returnUnits(item, qty) {
  return { ...item, reserved: item.reserved - qty };
}

function isStale(order, cutoff) {
  return order.status === 'reserved' && order.createdAt < cutoff;
}

/**
 * Write the SKU counters, then the order record, so an order's status only
 * changes after all of its counters have. If a write fails, the counters
 * already written are put back before the error is rethrown. The caller holds
 * the lock of every key involved. A rejected `set` is assumed not to have
 * been applied.
 */
async function writeAllOrNothing(store, skuWrites, orderWrite) {
  const written = [];
  try {
    // Sequential, so the first failure stops later writes and `written` is
    // exactly what has to be restored.
    for (const write of skuWrites) {
      await store.set(write.key, write.value);
      written.push(write);
    }
    await store.set(orderWrite.key, orderWrite.value);
  } catch (error) {
    await restore(store, written.reverse(), error);
    throw error;
  }
}

async function restore(store, writes, cause) {
  const failed = [];
  for (const write of writes) {
    try {
      await store.set(write.key, write.previous);
    } catch (error) {
      failed.push({ key: write.key, error });
    }
  }
  if (failed.length > 0) {
    const keys = failed.map(({ key }) => key).join(', ');
    throw new AggregateError(
      [cause, ...failed.map(({ error }) => error)],
      `store write failed, then restoring ${keys} failed too; those counters need manual repair`
    );
  }
}

function locksFor(store) {
  let locks = locksByStore.get(store);
  if (!locks) {
    locks = new KeyedMutex();
    locksByStore.set(store, locks);
  }
  return locks;
}

function skuKey(sku) {
  return `${SKU_PREFIX}${sku}`;
}

function orderKey(orderId) {
  return `${ORDER_PREFIX}${orderId}`;
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertStore(store) {
  if (!store || ['get', 'set', 'keys'].some(method => typeof store[method] !== 'function')) {
    throw new ValidationError('store must provide get, set and keys methods');
  }
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

module.exports = { InventoryService, DEFAULT_TTL_MS };
'use strict';

// In-memory key-value store with the latency profile of the Redis cluster
// used in production: every call yields to the event loop before it reads or
// writes, so concurrent callers interleave the way they do against the real
// store. Values are copied on the way in and out.
class Store {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await tick();
    const value = this.data.get(key);
    return value === undefined ? undefined : structuredClone(value);
  }

  async set(key, value) {
    await tick();
    this.data.set(key, structuredClone(value));
  }

  async keys(prefix) {
    await tick();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

module.exports = { Store };
'use strict';

const assert = require('node:assert/strict');
const { InventoryService, Store, UnknownOrderError } = require('../src');

/** A service stocked with `stock` ({ sku: qty }). */
async function stockedService(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

/** Let `n` rounds of store latency pass. */
async function ticks(n) {
  for (let i = 0; i < n; i++) {
    await new Promise(resolve => setImmediate(resolve));
  }
}

/** Reject with `message` if `promise` has not settled within `ms`. */
async function within(ms, promise, message) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(message)), ms);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

/** Resolves to true if `promise` settles within `ms`, false otherwise. */
async function settlesWithin(ms, promise) {
  let timer;
  const timeout = new Promise(resolve => {
    timer = setTimeout(() => resolve(false), ms);
  });
  try {
    return await Promise.race([promise.then(() => true, () => true), timeout]);
  } finally {
    clearTimeout(timer);
  }
}

/** Store whose calls for chosen keys can be held until the test lets them through. */
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  /**
   * Hold every get/set of `key` until `open()` is called. `arrived` resolves
   * when the first call for the key reaches the gate.
   */
  gate(key) {
    let open;
    let arrive;
    const opened = new Promise(resolve => { open = resolve; });
    const arrived = new Promise(resolve => { arrive = resolve; });
    this.gates.set(key, { opened, arrive });
    return {
      arrived,
      open: () => {
        this.gates.delete(key);
        open();
      }
    };
  }

  async get(key) {
    await this.pass(key);
    return super.get(key);
  }

  async set(key, value) {
    await this.pass(key);
    return super.set(key, value);
  }

  async pass(key) {
    const gate = this.gates.get(key);
    if (gate) {
      gate.arrive();
      await gate.opened;
    }
  }
}

/** Store that rejects chosen calls, to model a store outage mid-operation. */
class FlakyStore extends Store {
  constructor() {
    super();
    this.plans = new Map();
  }

  /** Reject the `calls`-th (1-based, counted from now) `method` calls on `key`. */
  fail(method, key, calls) {
    this.plans.set(`${method} ${key}`, { calls: new Set(calls), seen: 0 });
  }

  async get(key) {
    this.maybeFail('get', key);
    return super.get(key);
  }

  async set(key, value) {
    this.maybeFail('set', key);
    return super.set(key, value);
  }

  maybeFail(method, key) {
    const plan = this.plans.get(`${method} ${key}`);
    if (!plan) {
      return;
    }
    plan.seen += 1;
    if (plan.calls.has(plan.seen)) {
      throw new Error(`store unavailable: ${method} ${key}`);
    }
  }
}

/** Store that hands out and keeps live references instead of copies. */
class SharedReferenceStore {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    return this.data.get(key);
  }

  async set(key, value) {
    this.data.set(key, value);
  }

  async keys(prefix) {
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

/** Deterministic PRNG (mulberry32) so a failing random run can be replayed. */
function seededRandom(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Check every SKU's counters against the orders that exist.
 *
 * `added` is the total stock added per SKU; `orderIds` lists every orderId
 * the test tried to reserve. `reserved` must equal the units of reserved
 * orders, `sold` the units of committed orders, `stock` the units added minus
 * those sold, and available stock must not be negative.
 */
async function assertLedger(svc, added, orderIds) {
  const expected = Object.fromEntries(Object.keys(added).map(sku => [sku, { reserved: 0, sold: 0 }]));
  const statuses = { reserved: 0, committed: 0, released: 0, missing: 0 };
  for (const orderId of new Set(orderIds)) {
    let order;
    try {
      order = await svc.getOrder(orderId);
    } catch (error) {
      assert.ok(error instanceof UnknownOrderError, `unexpected error reading ${orderId}: ${error}`);
      statuses.missing += 1;
      continue;
    }
    statuses[order.status] += 1;
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') expected[sku].sold += qty;
    }
  }
  for (const [sku, total] of Object.entries(added)) {
    const snap = await svc.snapshot(sku);
    assert.deepEqual(
      snap,
      { sku, stock: total - expected[sku].sold, reserved: expected[sku].reserved, sold: expected[sku].sold },
      `counters for ${sku} do not match the order ledger`
    );
    assert.ok(snap.stock - snap.reserved >= 0, `${sku} has negative available stock`);
  }
  return statuses;
}

module.exports = {
  stockedService,
  ticks,
  within,
  settlesWithin,
  GatedStore,
  FlakyStore,
  SharedReferenceStore,
  seededRandom,
  assertLedger
};

